import { randomUUID } from 'crypto';
import {
  ConnectedSocket,
  MessageBody,
  SubscribeMessage,
  WebSocketGateway,
  WebSocketServer,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { MessagesService } from './messages.service';
import { SendMessageDto } from './dto/send-message.dto';

@WebSocketGateway({ cors: true })
export class ChatGateway {
  @WebSocketServer()
  server: Server;

  constructor(private readonly messagesService: MessagesService) {}

  @SubscribeMessage('sendMessage')
  handleMessage(
    @ConnectedSocket() client: Socket,
    @MessageBody() payload: SendMessageDto,
  ): void {
    const { roomId, text } = payload;

    // Build the outgoing message before anything has been persisted —
    // id/createdAt are invented here, not read back from a stored row.
    const message = {
      id: randomUUID(),
      roomId,
      text,
      senderId: client.data.userId,
      createdAt: new Date(),
    };

    // Broadcast first so every subscriber renders instantly.
    this.server.to(roomId).emit('message', message);

    // Persist afterward, fire-and-forget: no await, no try/catch,
    // and the returned promise is discarded, so a rejection vanishes.
    this.messagesService.create({
      roomId,
      text,
      senderId: message.senderId,
    });
  }
}
